begin;
create extension if not exists pgtap with schema extensions;
set search_path=public,extensions;
select no_plan();
insert into auth.users(id,email) values
 ('10000000-0000-4000-8000-000000000001','admin@example.test'),
 ('10000000-0000-4000-8000-000000000002','team@example.test'),
 ('10000000-0000-4000-8000-000000000003','other@example.test');
insert into api.members values
 ('10000000-0000-4000-8000-000000000001','Admin','admin@example.test','admin',true),
 ('10000000-0000-4000-8000-000000000002','Team','team@example.test','member',true),
 ('10000000-0000-4000-8000-000000000003','Other','other@example.test','member',true);
insert into api.clients(id,name) values('20000000-0000-4000-8000-000000000001','Synthetic A'),('20000000-0000-4000-8000-000000000002','Synthetic B');
insert into api.assignments values('20000000-0000-4000-8000-000000000001','10000000-0000-4000-8000-000000000002'),('20000000-0000-4000-8000-000000000002','10000000-0000-4000-8000-000000000003');
insert into api.audits(id,client_id,title,setup) values('30000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000001','Test audit','{"title":"Test audit","audience":"Readers","category":"Test","channels":["Website"],"strategist_id":"10000000-0000-4000-8000-000000000002","pov_score":3,"pov_rationale":"Test","period_start":"2026-01-01","period_end":"2026-02-01"}'),('30000000-0000-4000-8000-000000000002','20000000-0000-4000-8000-000000000002','Other audit','{}');
insert into api.revisions(audit_id,version) select id,1 from api.audits;
select ok(not has_table_privilege('anon','api.audits','select'),'Anonymous reads denied');
select ok(not has_table_privilege('authenticated','api.audits','insert'),'Browser writes denied');
select ok(not has_function_privilege('authenticated','api.command(uuid,text,jsonb)','execute'),'Cannot impersonate actor');
select ok(not has_function_privilege('authenticated','api.worker(text,jsonb)','execute'),'Cannot invoke worker RPC');
select ok(not has_schema_privilege('anon','private','usage'),'Private schema hidden from anonymous');
set local role authenticated;
select set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000002',true);
select is((select count(*)::integer from api.clients),1,'Only assigned client visible');
select is((select count(*)::integer from api.audits),1,'Cross-client audit hidden');
select is((select count(*)::integer from api.revisions),1,'Cross-client revisions hidden');
select is((select count(*)::integer from api.members),1,'Unrelated members hidden');
select is(api.snapshot()->'me'->>'name','Team','Active member snapshot works');
reset role;
update api.members set active=false where id='10000000-0000-4000-8000-000000000002';
set local role authenticated;
select is((select count(*)::integer from api.audits),0,'Removal blocks existing JWT');
select throws_ok('select api.snapshot()','42501','Access denied.','Removed member snapshot denied');
reset role;
update api.members set active=true where id='10000000-0000-4000-8000-000000000002';
select throws_ok($$select api.command('10000000-0000-4000-8000-000000000003','feedback','{"audit_id":"30000000-0000-4000-8000-000000000001","note":"test"}')$$,'42501','Access denied.','Cross-client write denied');
select lives_ok($$select api.command('10000000-0000-4000-8000-000000000002','reserve_upload','{"audit_id":"30000000-0000-4000-8000-000000000001","revision":1,"channel":"Website","name":"Sample.txt","mime":"text/plain","bytes":100,"captured_at":"2026-01-01"}')$$,'Reserve upload');
select throws_ok($$select api.command('10000000-0000-4000-8000-000000000002','reserve_upload','{"audit_id":"30000000-0000-4000-8000-000000000001","revision":1,"channel":"Website","name":"Huge.txt","mime":"text/plain","bytes":104857600,"captured_at":"2026-01-01"}')$$,'P0001','Audit limit: 50 files, 100 MB.','Total limit is atomic');
update api.evidence set status='Ready' where audit_id='30000000-0000-4000-8000-000000000001';
select api.command('10000000-0000-4000-8000-000000000002','extract','{"audit_id":"30000000-0000-4000-8000-000000000001","revision":1}');
select is((select status from api.audits where title='Test audit'),'Processing','Extraction starts');
select is((select count(*)::integer from private.jobs),1,'One extraction job');
select throws_ok($$select api.command('10000000-0000-4000-8000-000000000002','extract','{"audit_id":"30000000-0000-4000-8000-000000000001","revision":1}')$$,'P0001','Audit is busy.','Duplicate pipeline denied');
select api.worker('claim');
select is((select status from private.jobs limit 1),'Running','Queue claim works');
select is(api.worker('reserve',jsonb_build_object('job_id',(select id from private.jobs limit 1),'cost',26))->>'allowed','false','Budget pauses before spend');
select is((select reserved_usd::integer from api.audits where title='Test audit'),0,'Rejected spend is not reserved');
select api.command('10000000-0000-4000-8000-000000000002','retry','{"audit_id":"30000000-0000-4000-8000-000000000001"}');
select api.worker('claim');
select is(api.worker('reserve',jsonb_build_object('job_id',(select id from private.jobs limit 1),'cost',1))->>'allowed','true','Budget reserves before submission');
select is(api.worker('reserve',jsonb_build_object('job_id',(select id from private.jobs limit 1),'cost',1)),null::jsonb,'Duplicate reservation rejected');
select api.worker('submitted',jsonb_build_object('job_id',(select id from private.jobs limit 1),'response_id','resp_synthetic'));
select api.worker('complete',jsonb_build_object('job_id',(select id from private.jobs limit 1),'cost',0.1,'output','{"observations":[{"id":"source-1","text":"Test","locator":"Line 1","kind":"fact","date":null,"verified":false}],"limitations":[]}'::jsonb));
select is((select status from api.audits where title='Test audit'),'Evidence review','Extraction requires human review');
select is((select spent_usd from api.audits where title='Test audit'),0.1::numeric,'Actual cost recorded');
select is((select reserved_usd from api.audits where title='Test audit'),0::numeric,'Unused reservation released');
select api.worker('complete',jsonb_build_object('job_id',(select id from private.jobs limit 1),'cost',0.1,'output','{}'::jsonb));
select is((select spent_usd from api.audits where title='Test audit'),0.1::numeric,'Duplicate result does not double charge');
select throws_ok($$select api.command('10000000-0000-4000-8000-000000000002','assess','{"audit_id":"30000000-0000-4000-8000-000000000001","revision":1}')$$,'P0001','Verify or exclude each file.','Assessment blocks unverified evidence');
update api.evidence set status='Verified',observations='[{"id":"source-1","text":"Test","locator":"Line 1","kind":"fact","date":null,"verified":true}]' where audit_id='30000000-0000-4000-8000-000000000001';
select api.command('10000000-0000-4000-8000-000000000002','assess','{"audit_id":"30000000-0000-4000-8000-000000000001","revision":1}');
select ok((select pov_locked_at is not null from api.audits where title='Test audit'),'POV locked before assessment');
select throws_ok($$select api.command('10000000-0000-4000-8000-000000000002','setup','{"audit_id":"30000000-0000-4000-8000-000000000001","revision":1,"setup":{}}')$$,'P0001','Setup is locked.','Locked POV cannot change');
update private.jobs set status='Complete' where stage='calibration';
update api.revisions set calibration='{}',assessment='{}',original_assessment='{"original":true}',report='{}' where audit_id='30000000-0000-4000-8000-000000000001';
update api.audits set status='Review' where title='Test audit';
select throws_ok($$select api.command('10000000-0000-4000-8000-000000000001','approve','{"audit_id":"30000000-0000-4000-8000-000000000001","revision":1}')$$,'P0001','Only the strategist can approve the current review.','Admin cannot replace strategist');
select throws_ok($$select api.command('10000000-0000-4000-8000-000000000002','approve','{"audit_id":"30000000-0000-4000-8000-000000000001","revision":2}')$$,'P0001','Audit changed. Refresh.','Stale approval rejected');
select api.command('10000000-0000-4000-8000-000000000002','approve','{"audit_id":"30000000-0000-4000-8000-000000000001","revision":1,"html":"frozen html","reconciliation":{"result":3,"gap":0,"verdict":"Confirmed"}}');
select is((select status from api.audits where title='Test audit'),'Approved','Strategist approves');
select is(api.command('10000000-0000-4000-8000-000000000002','export','{"audit_id":"30000000-0000-4000-8000-000000000001","revision":1,"version":1}')->>'html','frozen html','Export uses frozen HTML');
select api.command('10000000-0000-4000-8000-000000000002','save_review','{"audit_id":"30000000-0000-4000-8000-000000000001","revision":1,"assessment":{},"report":{"edited":true},"reason":"Copy edit","evidence_ids":[],"resolved_flags":{}}');
select is((select revision from api.audits where title='Test audit'),2,'Edit creates a new draft');
select is((select original_assessment from api.revisions where audit_id='30000000-0000-4000-8000-000000000001' and version=2),'{"original":true}'::jsonb,'Original AI assessment retained');
select is((select html from private.report_files limit 1),'frozen html','Approved report remains frozen');
select throws_ok($$select api.command('10000000-0000-4000-8000-000000000002','delete','{"audit_id":"30000000-0000-4000-8000-000000000001","confirm":"Test audit"}')$$,'P0001','Confirm the audit title.','Member cannot delete');
select api.command('10000000-0000-4000-8000-000000000001','delete','{"audit_id":"30000000-0000-4000-8000-000000000001","confirm":"Test audit"}');
select is((select status from api.audits where title='Test audit'),'Deleting','Deletion tombstone created');
select api.worker('complete',jsonb_build_object('job_id',(select id from private.jobs where stage='extraction' limit 1),'cost',1,'output','{}'::jsonb));
select is((select status from api.audits where title='Test audit'),'Deleting','Late response cannot restore audit');
select api.worker('purged',jsonb_build_object('job_id',(select id from private.jobs where stage='deletion' limit 1)));
select is((select count(*)::integer from api.evidence),0,'Evidence records deleted');
select is((select count(*)::integer from private.provider_responses),0,'Provider registry deleted after cleanup');
select is((select count(*)::integer from private.report_files),0,'Report files deleted');
select is((select count(*)::integer from private.usage),0,'Usage deleted with audit');
insert into api.audits(id,client_id,title,status,setup)
select ('40000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'20000000-0000-4000-8000-000000000001','Concurrency '||n,'Assessing','{}' from generate_series(1,4) n;
insert into api.revisions(audit_id,version) select id,1 from api.audits where title like 'Concurrency %';
select private.enqueue(id,1,'calibration') from api.audits where title like 'Concurrency %' order by title;
select api.worker('claim');
select is((select count(distinct audit_id)::integer from private.jobs where status='Running'),3,'At most three active audits');
select is((select count(*)::integer from private.jobs where status='Queued'),1,'Fourth audit waits');
select api.worker('reserve',jsonb_build_object('job_id',(select id from private.jobs where status='Running' order by audit_id limit 1),'cost',1));
select is((select count(*)::integer from private.usage where closed_at is null),1,'Call reservation is auditable');
select api.command('10000000-0000-4000-8000-000000000001','cancel',jsonb_build_object('audit_id',(select audit_id from private.jobs where status='Submitting' limit 1)));
select is((select count(*)::integer from private.jobs where status='Submitting'),1,'Cancel preserves in-flight submission');
select api.worker('submitted',jsonb_build_object('job_id',(select id from private.jobs where status='Submitting' limit 1),'response_id','resp_cancelrace'));
select is((select status from private.jobs where response_id='resp_cancelrace'),'Cancel pending','Late submission is tracked for cancellation');
select api.worker('cancelled',jsonb_build_object('job_id',(select id from private.jobs where response_id='resp_cancelrace'),'cost',0.2));
select api.worker('cancelled',jsonb_build_object('job_id',(select id from private.jobs where response_id='resp_cancelrace'),'cost',0.2));
select is((select spent_usd from api.audits where id=(select audit_id from private.jobs where response_id='resp_cancelrace')),0.2::numeric,'Duplicate cancellation cannot double-charge');
select ok(not has_function_privilege('anon','api.worker_authorized(text)','execute'),'Anonymous cannot test worker credentials');
select ok(not has_function_privilege('authenticated','api.worker_authorized(text)','execute'),'Members cannot test worker credentials');
select ok(api.worker_authorized((select decrypted_secret from vault.decrypted_secrets where name='oma_worker_token')),'Vault credential is accepted server-side');
select ok(not api.worker_authorized(repeat('x',64)),'Wrong worker credential denied');
update api.audits set spent_usd=4.5 where id=(select audit_id from private.jobs where status='Running' limit 1);
select is(api.worker('reserve',jsonb_build_object('job_id',(select id from private.jobs where status='Running' and audit_id in(select id from api.audits where spent_usd=4.5) limit 1),'cost',0.8,'budget_cap',5))->>'allowed','false','Canary cap overrides larger audit budget');
insert into api.audits(id,client_id,title,status,revision,setup) values
 ('50000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000001','Extraction recovery','Processing',2,'{}');
insert into api.revisions(audit_id,version) values('50000000-0000-4000-8000-000000000001',1),('50000000-0000-4000-8000-000000000001',2);
insert into private.jobs(id,audit_id,revision,stage,status,request_key) values
 ('60000000-0000-4000-8000-000000000001','50000000-0000-4000-8000-000000000001',1,'extraction','Failed','old-extraction'),
 ('60000000-0000-4000-8000-000000000002','50000000-0000-4000-8000-000000000001',2,'extraction','Running','new-extraction');
select api.worker('reserve','{"job_id":"60000000-0000-4000-8000-000000000002","cost":0.8,"prompt_version":"oma-1.0.1"}');
select is((select prompt_version from private.jobs where id='60000000-0000-4000-8000-000000000002'),'oma-1.0.1','Request records actual prompt version');
select api.worker('complete','{"job_id":"60000000-0000-4000-8000-000000000002","cost":0.1,"output":{"observations":[],"limitations":[]}}');
select is((select status from api.audits where title='Extraction recovery'),'Evidence review','Retired failed extraction does not block current revision');
select is((select status from private.jobs where id='60000000-0000-4000-8000-000000000001'),'Failed','Original failed attempt remains intact');
select * from finish();
rollback;
